function categorizeWorkItem(title, description) {
  const combined = `${title} ${description}`.toLowerCase();  // lowercase once so every includes() test below is case-insensitive

  // Ignore pass runs FIRST and wins ties: a ticket mentioning both infra and UI is dropped here, not kept
  for (const keyword of IGNORE_KEYWORDS) {
    if (combined.includes(keyword.toLowerCase())) return 'ignore'; // short-circuit — never reaches the keep checks below
  }
  // Screens/visuals -> 'ui'; first match wins, so the order of these buckets IS the precedence
  const uiKeywords = ['ui','screen','page','modal','button','form','layout','design'];
  for (const keyword of uiKeywords)
    if (combined.includes(keyword)) return 'ui';
  // Behaviour/logic -> 'functionality', checked only after UI so a form-validation ticket reads as UI
  const funcKeywords = ['feature','logic','implement','validation','workflow'];
  for (const keyword of funcKeywords)
    if (combined.includes(keyword)) return 'functionality';

  return 'other'; // NOT a skip — unmatched tickets are still kept in the briefing, just uncategorized
}

async function loadFeatureFolderContext(config) {
  const sources = []; // one flat list — every doc becomes a uniform { type, content, ... } entry regardless of origin

  // 1. Local story exports (ADO work items previously saved to disk) seed the list
  sources.push(...loadLocalAdoStories(config.adoDir));

  // 2. Design docs live under any of several conventional folder names — probe each; teams don't agree on one
  for (const name of ['design','figma','designs','wireframes']) {
    const dir = path.join(config.basePath, name);
    if (fs.existsSync(dir)) // existsSync guard: a folder the team never created is skipped, not thrown on
      sources.push(...await loadDirectoryContext(dir, 'design')); // tag 'design' so later extraction knows how to read it
  }
  // 3. Transcripts are loaded elsewhere — they need LLM analysis, not plain text extraction
  return sources;
}

async function analyzeTranscriptWithLLM(transcript, featureContext) {
  // substring caps are a token-budget guard: 2k of context + 6k of transcript — the head of each carries
  // the demoed behavior, and a long recording can't overflow the context window or spike cost
  const prompt = `You are a QA analyst extracting testable
information from a meeting/demo transcript.

FEATURE CONTEXT:
${featureContext.substring(0, 2000)}

TRANSCRIPT:
${transcript.substring(0, 6000)}

Extract as JSON:
{
  "demonstratedFeatures": ["..."],
  "testableScenarios": [{ "scenario": "...", "steps": ["..."] }],
  "businessRules": ["..."],
  "edgeCases": [{ "scenario": "...", "priority": "high|medium|low" }]
}`;
  const res = await callGeminiFlash(prompt); // Gemini Flash: the cheap/fast tier, ample for extraction-style work
  return parseLLMJson(res.answer); // tolerant parse — models wrap JSON in markdown fences/prose; this salvages it
}

async function buildFeatureIntelligence(storyId, storyTitle, sources) {
  // Rule-based, deterministic passes over EVERY source — no model call, so these are stable across runs
  const uiComponents  = extractUIComponents(sources);
  const userFlows     = extractUserFlows(sources);
  const businessRules = extractBusinessRules(sources);
  const edgeCases     = extractEdgeCases(sources);

  // Transcript-only: mine decisions the rule passes can't infer, by slicing the '## Decisions Made' section
  const walkthrough = { decisionsRecorded: [], questionsRaised: [] }; // accumulator for decisions/open-questions surfaced across all transcripts
  for (const ts of sources.filter(s => s.type === 'transcript')) {
    const decisions = ts.content.match(/## Decisions Made\n([\s\S]*?)(?=\n##|$)/);
    if (decisions) walkthrough.decisionsRecorded.push(...parseList(decisions[1])); // decisions[1] = the captured section body; parseList splits its bullets
  }
  return { storyId, storyTitle, userFlows, businessRules,
           edgeCases, walkthrough, confidenceScore: score(sources) }; // score() weights how many source TYPES were present — thin input yields a lower score
}

function saveVersion(outputDir, storyId, version) {
  const versionFile = getVersionFilePath(outputDir, storyId); // stable per-story path, so a re-run overwrites in place instead of piling up copies
  fs.mkdirSync(path.dirname(versionFile), { recursive: true }); // recursive: builds the whole tree, no-op if it exists — safe on a fresh checkout
  fs.writeFileSync(versionFile, JSON.stringify(version, null, 2)); // 2-space pretty-print keeps the briefing diff-friendly; version carries the content hashes
}
